def axmm(fig,x,y,w,h):
 return fig.add_axes([x/W,y/H,w/W,h/H],facecolor=PAPER)
def txt(fig,x,y,s,size=7,weight="regular",**kw):
 return fig.text(x/W,y/H,s,fontsize=size,fontweight=weight,va=kw.pop("va","top"),
                 color=kw.pop("color",INK),zorder=30,**kw)
def naked(ax):
 for s in ax.spines.values():s.set_visible(False)
 ax.tick_params(length=0,pad=1.4,colors=INK);ax.set_axisbelow(True)
def heading(fig,letter,x,y,label):
 txt(fig,3 if x<100 else x-6,y+.3,letter,9.2,"bold")
 txt(fig,x,y,label,8)
def tile(ax,x,y,v,norm,w=.94,h=.86,number=None,gid=None):
 p=Rectangle((x-w/2,y-h/2),w,h,fc=D_CMAP(norm(v)),ec=PAPER,lw=.28,zorder=2)
 p.set_gid(gid);ax.add_patch(p)
 if number is not None:
  ax.text(x,y,number,ha="center",va="center",fontsize=7,
          color=PAPER if abs(float(norm(v))-.5)>.36 else INK,zorder=30,linespacing=.95)
def signed(v):
 # Retain the magnitude of small negative values instead of printing negative zero.
 if v==0:return "0"
 if abs(v)<.005:
  decimals=max(3,int(-np.floor(np.log10(abs(v)))))
  return f"{v:+.{decimals}f}".replace("-","−")
 return f"{v:+.2f}"
def colorbar(fig,x,y,w,norm,cmap,ticks,labels,label):
 ax=axmm(fig,x,y,w,1.8);naked(ax)
 edges=np.linspace(norm.vmin,norm.vmax,129)
 for a,b in zip(edges[:-1],edges[1:]):
  ax.add_patch(Rectangle((a,0),b-a,1,fc=cmap(norm((a+b)/2)),ec="none",zorder=2))
 ax.set(xlim=(norm.vmin,norm.vmax),ylim=(0,1),yticks=[])
 ax.set_xticks(ticks);ax.set_xticklabels(labels);ax.set_xlabel(label,labelpad=1.2)
 ax.tick_params(axis="x",length=1.8,width=.4,pad=1)
 for s in ax.spines.values():s.set_visible(True);s.set_linewidth(.4);s.set_color(INK)
 return ax

def multiscale(fig):
 heading(fig,"a",35,246.3,"Noise-corrected correlation, q: neighbouring versus non-neighbouring")
 handles=[
  Line2D([],[],marker="s",mfc=MID,mec=PAPER,mew=.2,ms=2.7,lw=0,label="Non-neighbouring pairs"),
  Line2D([],[],marker="o",mfc=MID,mec=PAPER,mew=.2,ms=2.7,lw=0,label="Neighbouring pairs"),
  Line2D([],[],marker="s",mfc=MID,mec=PAPER,mew=.2,ms=4.2,lw=0,label="Change")]
 fig.legend(handles=handles,loc="upper left",bbox_to_anchor=(35/W,240.4/H),
   ncol=3,frameon=False,handlelength=.65,handletextpad=.35,columnspacing=.8,borderpad=.02)
 ax=axmm(fig,35,171,111,58);naked(ax)
 am=axmm(fig,151,171,25,58);naked(am)
 for mi,m in enumerate(MODELS):
  base=mi*3.
